package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.view.View;
import android.widget.*;
import org.json.*;
import java.util.*;
/** Search, review each catalog draft, then save sequentially with confirmed progress. */
final class CatalogAddDialog {
 private final Context c;private String owner;private final boolean media;private final Runnable saved;private final AccountRepository repo;private final NativeSheet sheet;
 private final EditText query;private final Spinner type,batchStatus;private final TextView state;private final LinearLayout results,selection;private final Button search,save;
 private final Map<CheckBox,String[]> checks=new LinkedHashMap<>();private boolean syncingChecks;private final List<JSONObject> drafts=new ArrayList<>();private int generation,pending,confirmed,skipped;private boolean busy,changed,uncertain,reviewing,autoSave;
 CatalogAddDialog(Context c,boolean media,int initialType,JSONObject selected,Runnable saved){this.c=c;owner=c.getSharedPreferences("batcaverna",0).getString("user_id","");this.media=media;this.saved=saved;repo=new AccountRepository(c);sheet=new NativeSheet(c,media?"🍿 Adicionar títulos":"🎮 Adicionar jogos");
  type=NativeSheet.options(c,MediaInput.TYPES);type.setSelection(Math.max(0,Math.min(2,initialType)));if(media)sheet.body.addView(type);
  query=NativeSheet.input(c,media?"Buscar filme, série ou anime":"Buscar jogo",100);query.setSingleLine(true);sheet.body.addView(query);
  search=button("Buscar no catálogo",false);sheet.body.addView(search);state=NativeSheet.text(c,"",13,0xffbcaaff);sheet.body.addView(state);
  results=new LinearLayout(c);results.setOrientation(LinearLayout.VERTICAL);sheet.body.addView(results);
  Button manual=button("＋ Adicionar pelo nome",false);sheet.body.addView(manual);manual.setOnClickListener(v->{if(busy)return;try{JSONObject row=new JSONObject().put("nome",GameInput.name(query.getText().toString()));choose(row,type.getSelectedItemPosition(),true);}catch(Exception e){state.setText(e.getMessage());}});
  sheet.body.addView(NativeSheet.text(c,"✓ Selecionados",16,0xffe7dbff));batchStatus=NativeSheet.options(c,media?MediaInput.STATUS:GameInput.STATUSES);sheet.body.addView(batchStatus);Button applyStatus=button("Aplicar status aos selecionados",false);sheet.body.addView(applyStatus);applyStatus.setOnClickListener(v->{if(busy)return;try{for(JSONObject d:drafts)d.put("_status",batchStatus.getSelectedItemPosition());renderSelection();}catch(JSONException ignored){}});selection=new LinearLayout(c);selection.setOrientation(LinearLayout.VERTICAL);sheet.body.addView(selection);
  sheet.footer.setVisibility(View.VISIBLE);save=button("Adicionar à biblioteca",true);sheet.footer.addView(save);save.setOnClickListener(v->submit());
  search.setOnClickListener(v->search());query.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){generation++;}});
  type.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){generation++;results.removeAllViews();}});
  sheet.dialog.setOnDismissListener(d->{generation++;if(changed)saved.run();});sheet.show();renderSelection();if(selected!=null)choose(selected,initialType,true);
 }
 CatalogAddDialog(Context c,boolean media,int initialType,JSONArray list,Runnable saved,boolean batch){this(c,media,initialType,(JSONObject)null,saved);for(int i=0;i<list.length();i++){JSONObject row=list.optJSONObject(i);if(row!=null)choose(row,initialType,false);}autoSave=batch;tryAutoSave();}
 private Button button(String label,boolean primary){Button b=new Button(c);b.setText(label);AppStyle.button(b,primary);return b;}
 private void search(){if(busy)return;final int ticket=++generation,kind=type.getSelectedItemPosition();search.setEnabled(false);results.removeAllViews();checks.clear();state.setText("Buscando…");AccountRepository.Callback cb=(rows,error)->{if(!sheet.dialog.isShowing())return;search.setEnabled(!busy);if(ticket!=generation)return;if(error!=null){state.setText(error);return;}state.setText(rows.length()==0?"Nenhum título encontrado.":"Selecione os títulos ou toque na capa para revisar.");for(int i=0;i<rows.length();i++){JSONObject item=rows.optJSONObject(i);if(item==null)continue;String name=item.optString(media?"nome":"name",item.optString("nome"));try{GameInput.name(name);}catch(Exception e){continue;}LinearLayout line=new LinearLayout(c);line.setGravity(android.view.Gravity.CENTER_VERTICAL);CheckBox check=new CheckBox(c);check.setButtonTintList(android.content.res.ColorStateList.valueOf(0xffac86ff));check.setContentDescription("Selecionar "+name);check.setChecked(find(name,kind)!=null);checks.put(check,new String[]{name,String.valueOf(kind)});line.addView(check);LinearLayout art=CatalogCard.create(c,name,item.optString(media?"capa":"background_image"));line.addView(art,new LinearLayout.LayoutParams(0,-2,1));results.addView(line);check.setOnCheckedChangeListener((b,on)->{if(busy||syncingChecks)return;if(on)choose(item,kind,false);else{JSONObject found=find(name,kind);if(found!=null)drafts.remove(found);renderSelection();}});art.setOnClickListener(v->{if(busy)return;JSONObject found=find(name,kind);if(found!=null){if(!found.optBoolean("_loading"))edit(found);}else{choose(item,kind,true);}});}};if(media)repo.searchMedia(query.getText().toString(),kind,cb);else repo.searchGames(query.getText().toString(),cb);}
 private JSONObject find(String name,int kind){for(JSONObject d:drafts)if(d.optString("nome").equalsIgnoreCase(name.trim())&&(!media||d.optInt("_type")==kind))return d;return null;}
 private void choose(JSONObject source,int kind,boolean open){String name=source.optString("nome",source.optString("name"));JSONObject existing=find(name,kind);if(existing!=null){if(open&&!existing.optBoolean("_loading"))edit(existing);return;}if(drafts.size()>=50){state.setText("Adicione até 50 títulos por vez.");renderSelection();return;}try{if(source.optBoolean("adult"))throw new IllegalArgumentException("Este conteúdo não é permitido.");GameInput.name(name);JSONObject d=new JSONObject(source.toString());d.put("nome",name).put("capa",source.optString("capa",source.optString("background_image"))).put("_type",kind).put("_status",batchStatus.getSelectedItemPosition()).put("nota","🤔 A considerar").put("prioridade","⚖️ Média").put("plataforma","💻 PC").put("loja","🟦 Steam").put("horas","0");String released=source.optString("released","");if(!d.has("ano")&&released.matches("[12][0-9]{3}.*"))d.put("ano",released.substring(0,4));if(source.optInt("playtime")>0)d.put("tempo_est",String.valueOf(source.optInt("playtime")));flattenGenres(d);drafts.add(d);
  boolean hasId=source.optLong(media?"catalog_id":"id")>0;if(!hasId){renderSelection();if(open)edit(d);return;}
  d.put("_loading",true);pending++;renderSelection();repo.catalogDetails(source,media,kind,(rows,error)->{pending--;if(!sheet.dialog.isShowing())return;if("Este conteúdo não é permitido.".equals(error)){drafts.remove(d);state.setText(error);renderSelection();return;}try{if(drafts.contains(d)){if(error==null&&rows.length()>0){JSONObject detail=rows.optJSONObject(0);for(String key:new String[]{"ano","generos","duracao","onde","capa","sinopse","tempo_est","steam_appid","preco","loja"})if(detail.has(key)&&!detail.isNull(key))d.put(key,detail.opt(key));flattenGenres(d);}else state.setText("Alguns detalhes não vieram do catálogo. Revise o título.");d.put("_loading",false);renderSelection();if(open)edit(d);}else renderSelection();}catch(JSONException e){state.setText("Não foi possível completar os detalhes.");}});
 }catch(Exception e){state.setText(e.getMessage());}}
 private static void flattenGenres(JSONObject d)throws JSONException{JSONArray a=d.optJSONArray("generos");if(a==null)return;List<String> names=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject g=a.optJSONObject(i);String n=g==null?a.optString(i):g.optString("name");if(!n.isEmpty())names.add(n);}d.put("generos",android.text.TextUtils.join(", ",names));}
 private void renderSelection(){syncingChecks=true;for(Map.Entry<CheckBox,String[]> entry:checks.entrySet()){String[] value=entry.getValue();entry.getKey().setChecked(find(value[0],Integer.parseInt(value[1]))!=null);entry.getKey().setEnabled(!busy);}syncingChecks=false;selection.removeAllViews();for(JSONObject d:drafts){LinearLayout row=new LinearLayout(c);row.setGravity(android.view.Gravity.CENTER_VERTICAL);LinearLayout card=CatalogCard.create(c,d.optString("nome")+(d.optBoolean("_loading")?" • carregando…":""),d.optString("capa"));row.addView(card,new LinearLayout.LayoutParams(0,-2,1));card.setOnClickListener(v->{if(!busy&&!d.optBoolean("_loading"))edit(d);});Button remove=button("×",false);remove.setContentDescription("Remover "+d.optString("nome")+" da seleção");remove.setEnabled(!busy);row.addView(remove,new LinearLayout.LayoutParams(NativeSheet.dp(c,48),NativeSheet.dp(c,48)));remove.setOnClickListener(v->{drafts.remove(d);renderSelection();});selection.addView(row);selection.addView(NativeSheet.text(c,(media?MediaInput.TYPES[d.optInt("_type")]+" • ":"")+(media?MediaInput.STATUS:GameInput.STATUSES)[d.optInt("_status")]+" • "+d.optString("ano",""),12,0xffb1bfce));}
  save.setText(busy?"Salvando…":pending>0?"Completando detalhes…":"Adicionar "+drafts.size()+" título(s)");save.setEnabled(!busy&&!uncertain&&pending==0&&!drafts.isEmpty());tryAutoSave();}
 private EditText field(NativeSheet form,String label,String key,JSONObject d,int max){form.body.addView(NativeSheet.text(c,label,12,0xffbba7df));EditText e=NativeSheet.input(c,label,max);e.setText(d.isNull(key)?"":d.optString(key));form.body.addView(e);return e;}
 private void edit(JSONObject d){if(reviewing){state.setText("Conclua a revisão aberta antes de revisar outro título.");return;}reviewing=true;NativeSheet form=new NativeSheet(c,"Revisar título");form.dialog.setOnDismissListener(v->{reviewing=false;tryAutoSave();});ImageView image=new ImageView(c);image.setScaleType(ImageView.ScaleType.FIT_CENTER);form.body.addView(image,new LinearLayout.LayoutParams(-1,NativeSheet.dp(c,140)));AccountImageLoader.load(image,d.optString("capa"));Map<String,EditText> fields=new LinkedHashMap<>();fields.put("nome",field(form,"Nome","nome",d,160));
  String synopsis=d.optString("sinopse");if(!synopsis.isEmpty()){TextView desc=NativeSheet.text(c,synopsis,12,0xffaab9cb);desc.setMaxLines(5);desc.setOnClickListener(v->desc.setMaxLines(desc.getMaxLines()==5?Integer.MAX_VALUE:5));form.body.addView(desc);}
  form.body.addView(NativeSheet.text(c,"Status",12,0xffbba7df));Spinner status=NativeSheet.options(c,media?MediaInput.STATUS:GameInput.STATUSES);status.setSelection(d.optInt("_status"));form.body.addView(status);
  form.body.addView(NativeSheet.text(c,"Sua nota",12,0xffbba7df));Spinner rating=NativeSheet.options(c,ItemEditInput.RATINGS);for(int i=0;i<ItemEditInput.RATINGS.length;i++)if(ItemEditInput.RATINGS[i].equals(d.optString("nota")))rating.setSelection(i);form.body.addView(rating);
  PlatformSelector platforms=new PlatformSelector(c);platforms.setValue(d.optString("plataforma","💻 PC"));Spinner store=NativeSheet.options(c,ItemEditInput.preserve(new String[]{"🟦 Steam","🟣 Epic Games","🟢 GOG","🔵 PlayStation Store","🟩 Xbox Store","🔴 eShop","Outro"},d.optString("loja")));Spinner priority=NativeSheet.options(c,new String[]{"⚖️ Média","🔥 Alta","❄️ Baixa"});for(int i=0;i<store.getCount();i++)if(store.getItemAtPosition(i).equals(d.optString("loja")))store.setSelection(i);for(int i=0;i<priority.getCount();i++)if(priority.getItemAtPosition(i).equals(d.optString("prioridade")))priority.setSelection(i);
  if(!media){form.body.addView(NativeSheet.text(c,"Plataformas",12,0xffbba7df));form.body.addView(platforms);form.body.addView(NativeSheet.text(c,"Loja",12,0xffbba7df));form.body.addView(store);form.body.addView(NativeSheet.text(c,"Prioridade",12,0xffbba7df));form.body.addView(priority);}else{fields.put("onde",field(form,"Onde assistir","onde",d,80));Button providers=button("Selecionar serviços de streaming",false);form.body.addView(providers);providers.setOnClickListener(v->services(fields.get("onde")));fields.put("duracao",field(form,"Duração / temporadas / episódios","duracao",d,80));}
  fields.put("ano",field(form,"Ano de lançamento","ano",d,4));fields.put("generos",field(form,"Gêneros","generos",d,500));if(!media){fields.put("horas",field(form,"Horas jogadas","horas",d,12));fields.put("tempo_est",field(form,"Tempo para zerar (h)","tempo_est",d,80));fields.put("conquistas",field(form,"Conquistas (%)","conquistas",d,12));fields.put("preco",field(form,"Preço (R$)","preco",d,12));}
  fields.put("inicio",field(form,"Início • AAAA-MM-DD","inicio",d,10));fields.put("data",field(form,media?"Assistido em • AAAA-MM-DD":"Finalizado em • AAAA-MM-DD","data",d,10));for(String key:new String[]{"inicio","data"}){EditText e=fields.get(key);e.setFocusable(false);e.setOnClickListener(v->{Calendar cal=Calendar.getInstance();String raw=e.getText().toString();if(raw.matches("[12][0-9]{3}-[0-9]{2}-[0-9]{2}")){cal.set(Integer.parseInt(raw.substring(0,4)),Integer.parseInt(raw.substring(5,7))-1,Integer.parseInt(raw.substring(8,10)));}new android.app.DatePickerDialog(c,(picker,y,m,day)->e.setText(String.format(Locale.ROOT,"%04d-%02d-%02d",y,m+1,day)),cal.get(Calendar.YEAR),cal.get(Calendar.MONTH),cal.get(Calendar.DAY_OF_MONTH)).show();});e.setOnLongClickListener(v->{e.setText("");return true;});}
  fields.put("review",field(form,"Sua avaliação / anotações","review",d,4000));fields.get("review").setMinLines(3);fields.put("capa",field(form,"URL da capa","capa",d,2000));TextView error=NativeSheet.text(c,"",13,0xffffa4ac);form.body.addView(error);Button apply=button("✓ Usar estes detalhes",true);form.footer.setVisibility(View.VISIBLE);form.footer.addView(apply);apply.setOnClickListener(v->{try{JSONObject edited=new JSONObject(d.toString());for(Map.Entry<String,EditText> f:fields.entrySet())edited.put(f.getKey(),f.getValue().getText().toString().trim());edited.put("_status",status.getSelectedItemPosition()).put("nota",rating.getSelectedItemPosition()==0?"":rating.getSelectedItem().toString());if(!media)edited.put("plataforma",platforms.value()).put("loja",store.getSelectedItem()).put("prioridade",priority.getSelectedItem());validate(edited);for(Iterator<String> it=edited.keys();it.hasNext();){String key=it.next();d.put(key,edited.opt(key));}renderSelection();form.dialog.dismiss();}catch(Exception e){error.setText(e.getMessage());}});form.show();}
 private void services(EditText target){NativeSheet picker=new NativeSheet(c,"Onde assistir");String[] options={"Netflix","Max","Crunchyroll","Amazon Prime Video","Disney Plus","Apple TV","Paramount Plus","YouTube","Cinema","Outro"};List<String> picked=new ArrayList<>();for(String part:target.getText().toString().split(" • "))if(!part.trim().isEmpty())picked.add(part.trim());for(String option:options){CheckBox check=new CheckBox(c);check.setText(option);check.setTextColor(0xffeee6fc);check.setButtonTintList(android.content.res.ColorStateList.valueOf(0xffae85ff));check.setChecked(picked.contains(option));picker.body.addView(check);check.setOnCheckedChangeListener((b,on)->{if(on&&!picked.contains(option))picked.add(option);if(!on)picked.remove(option);});}TextView error=NativeSheet.text(c,"",12,0xffffa4ac);picker.body.addView(error);Button apply=button("Usar serviços selecionados",true);picker.footer.setVisibility(View.VISIBLE);picker.footer.addView(apply);apply.setOnClickListener(v->{String value=android.text.TextUtils.join(" • ",picked);if(value.length()>80){error.setText("Selecione até 80 caracteres de serviços.");return;}target.setText(value);picker.dialog.dismiss();});picker.show();}
 private void validate(JSONObject d){CatalogDraftInput.validate(d.optString("nome"),d.optString("ano"),d.optString("generos"),d.optString("inicio"),d.optString("data"),d.optString("review"));ItemInfoInput.validate(d.optString("nome"),d.optString("plataforma"),d.optString("loja"),d.optString("ano"),d.optString("prioridade"),d.optString("tempo_est"),d.optString("conquistas"),d.optString("generos"),d.optString("preco"));if(media)MediaInput.validate(d.optString("nome"),d.optInt("_type"),d.optInt("_status"),d.optString("onde"),d.optString("duracao"));else{GameInput.hours(d.optString("horas","0"));if(!d.optString("tempo_est").isEmpty())GameInput.hours(d.optString("tempo_est"));if(d.optString("plataforma").isEmpty())throw new IllegalArgumentException("Selecione ao menos uma plataforma.");}}
 private void tryAutoSave(){if(autoSave&&!reviewing&&!busy&&!uncertain&&pending==0&&!drafts.isEmpty()&&sheet.dialog.isShowing()){autoSave=false;submit();}}
 private void submit(){if(!owner.equals(c.getSharedPreferences("batcaverna",0).getString("user_id",""))){state.setText("A sessão mudou. Reabra a tela com sua conta.");return;}if(busy||pending>0||uncertain)return;for(JSONObject d:drafts)try{validate(d);}catch(Exception e){state.setText(d.optString("nome")+": "+e.getMessage());edit(d);return;}busy=true;sheet.busy(true);search.setEnabled(false);query.setEnabled(false);type.setEnabled(false);batchStatus.setEnabled(false);generation++;confirmed=skipped=0;renderSelection();saveNext();}
 private void saveNext(){if(!owner.equals(c.getSharedPreferences("batcaverna",0).getString("user_id",""))){sheet.busy(false);sheet.dialog.dismiss();return;}if(drafts.isEmpty()){busy=false;sheet.busy(false);Toast.makeText(c,confirmed+" adicionado(s)"+(skipped>0?" • "+skipped+" já na biblioteca":""),Toast.LENGTH_LONG).show();sheet.dialog.dismiss();return;}JSONObject d=drafts.get(0);state.setText("Salvando "+d.optString("nome")+" • "+confirmed+" confirmado(s)");repo.addCatalogItem(d,media,(rows,error)->{if(!sheet.dialog.isShowing()||!owner.equals(c.getSharedPreferences("batcaverna",0).getString("user_id","")))return;if(error!=null){busy=false;uncertain=true;sheet.busy(false);state.setText(confirmed+" salvo(s). "+d.optString("nome")+": "+error+" Confira a biblioteca antes de tentar novamente. Os demais não foram enviados.");renderSelection();return;}if(rows.optJSONObject(0)!=null&&rows.optJSONObject(0).optBoolean("skipped")){skipped++;changed=true;}else{confirmed++;changed=true;}drafts.remove(0);renderSelection();saveNext();});}
}
